FROM family_member fm1
INNER JOIN family_member fm2 ON fm1.family_id = fm2.family_id
WHERE fm1.user_id = #{userId1, typeHandler=com.echoes.user.domain.user.repository.typehandler.BinaryUuidTypeHandler}
  AND fm2.user_id = #{userId2, typeHandler=com.echoes.user.domain.user.repository.typehandler.BinaryUuidTypeHandler}
